export function parse(phrase: string): string {
  // Replace hyphens with spaces to treat them as word separators
  const normalizedPhrase = phrase.replace(/-/g, ' ');

  // Remove all non-alphanumeric characters except spaces
  const cleanedPhrase = normalizedPhrase.replace(/[^a-zA-Z0-9\s]/g, '');

  // Split the string by whitespace to get individual words
  const words = cleanedPhrase.split(/\s+/).filter(word => word.length > 0);

  // Take the first letter of each word, convert to uppercase, and join them
  const acronym = words.map(word => word[0].toUpperCase()).join('');

  return acronym;
}
